DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM identity."__EFMigrationsHistory" WHERE "MigrationId" = '20261013144939_AddFgsUserGridPreference') THEN
    CREATE TABLE identity."FgsUserGridPreference" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "UserId" uuid NOT NULL,
        "GridCode" character varying(100) NOT NULL,
        "GridConfiguration" jsonb NOT NULL DEFAULT ('{}'::jsonb),
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        CONSTRAINT "PK_FgsUserGridPreference" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_FgsUserGridPreference_FgsTenantCompanyCache" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES identity."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT,
        CONSTRAINT "FK_FgsUserGridPreference_FgsUser" FOREIGN KEY ("UserId", "TenantId", "CompanyId") REFERENCES identity."FgsUser" ("Id", "TenantId", "CompanyId") ON DELETE CASCADE
    );
    COMMENT ON TABLE identity."FgsUserGridPreference" IS 'Stores user-specific grid layout and display preferences for each grid within a tenant and company.';
    COMMENT ON COLUMN identity."FgsUserGridPreference"."Id" IS 'Unique identifier for the user grid preference record.';
    COMMENT ON COLUMN identity."FgsUserGridPreference"."TenantId" IS 'Identifier of the tenant to which the user and grid preference belong.';
    COMMENT ON COLUMN identity."FgsUserGridPreference"."CompanyId" IS 'Identifier of the company within the tenant to which the user and grid preference belong.';
    COMMENT ON COLUMN identity."FgsUserGridPreference"."UserId" IS 'Identifier of the user whose grid preference is being stored.';
    COMMENT ON COLUMN identity."FgsUserGridPreference"."GridCode" IS 'Unique application-defined code identifying the grid for which the user preferences are stored, such as WorkOrderList or EstimateList.';
    COMMENT ON COLUMN identity."FgsUserGridPreference"."GridConfiguration" IS 'JSON configuration containing user-specific grid preferences such as column width, visibility, display order, pinning, sorting, filtering, grouping, and other supported grid settings.';
    COMMENT ON COLUMN identity."FgsUserGridPreference"."CreatedOn" IS 'UTC timestamp when the user grid preference record was created.';
    COMMENT ON COLUMN identity."FgsUserGridPreference"."CreatedBy" IS 'Identifier of the user or process that created the user grid preference record.';
    COMMENT ON COLUMN identity."FgsUserGridPreference"."UpdatedOn" IS 'UTC timestamp when the user grid preference record was last updated.';
    COMMENT ON COLUMN identity."FgsUserGridPreference"."UpdatedBy" IS 'Identifier of the user or process that last updated the user grid preference record.';
    END IF;
END $EF$;

